package com.company.tpm.telegram;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;
@Service public class TelegramLinkTokenService{private final SecureRandom random=new SecureRandom();public record Generated(String raw,String hash,Instant expiresAt){}public Generated generate(Duration ttl){byte[]b=new byte[32];random.nextBytes(b);String raw=Base64.getUrlEncoder().withoutPadding().encodeToString(b);return new Generated(raw,hash(raw),Instant.now().plus(ttl));}public boolean matches(String raw,String expectedHash){return MessageDigest.isEqual(hash(raw).getBytes(StandardCharsets.UTF_8),expectedHash.getBytes(StandardCharsets.UTF_8));}private String hash(String raw){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}}
